//! Safe wrappers around cb-mpc's TDH2 threshold decryption (`include/cbmpc/c_api/tdh2.h`).
//!
//! Used for the per-commitment (revocation) secrets: an offline ceremony encrypts each secret
//! under the parties' joint TDH2 public key, bound by a label to its kit and commitment number.
//! A secret can only be recovered when every party contributes a partial decryption, which each
//! does only after its own policy allows the release.
//!
//! The key is generated by a distributed key generation; no party ever holds the decryption key.
//! It is a dedicated key and must never be one of the ECDSA signing keys.

use std::ffi::CString;
use std::fmt;
use std::os::raw::{c_char, c_int, c_void};
use std::panic::{catch_unwind, AssertUnwindSafe};

use crate::cbmpc::{CbmpcError, ProtocolError, Transport, TransportError};
use crate::ffi;

fn check(code: ffi::cbmpc_error_t) -> Result<(), CbmpcError> {
	if code == ffi::CBMPC_SUCCESS {
		Ok(())
	} else {
		Err(CbmpcError { code })
	}
}

fn view(bytes: &[u8]) -> ffi::cmem_t {
	ffi::cmem_t { data: bytes.as_ptr() as *mut u8, size: bytes.len() as c_int }
}

unsafe fn take_cmem(mem: ffi::cmem_t) -> Vec<u8> {
	if mem.data.is_null() || mem.size <= 0 {
		if !mem.data.is_null() {
			ffi::cbmpc_cmem_free(mem);
		}
		return Vec::new();
	}
	let out = std::slice::from_raw_parts(mem.data, mem.size as usize).to_vec();
	ffi::cbmpc_cmem_free(mem);
	out
}

unsafe fn take_cmems(mems: ffi::cmems_t) -> Vec<Vec<u8>> {
	let mut out = Vec::new();
	if mems.count > 0 && !mems.sizes.is_null() {
		let sizes = std::slice::from_raw_parts(mems.sizes, mems.count as usize);
		let mut offset = 0usize;
		for size in sizes {
			let size = (*size).max(0) as usize;
			if size == 0 || mems.data.is_null() {
				out.push(Vec::new());
			} else {
				out.push(std::slice::from_raw_parts(mems.data.add(offset), size).to_vec());
			}
			offset += size;
		}
	}
	ffi::cbmpc_cmems_free(mems);
	out
}

/// A flattened list of byte slices in cb-mpc's `cmems_t` layout, borrowed for one call.
struct Flat {
	data: Vec<u8>,
	sizes: Vec<c_int>,
}

impl Flat {
	fn new(items: &[Vec<u8>]) -> Self {
		let mut data = Vec::new();
		let mut sizes = Vec::with_capacity(items.len());
		for item in items {
			data.extend_from_slice(item);
			sizes.push(item.len() as c_int);
		}
		Flat { data, sizes }
	}

	fn view(&mut self) -> ffi::cmems_t {
		ffi::cmems_t {
			count: self.sizes.len() as c_int,
			data: self.data.as_mut_ptr(),
			sizes: self.sizes.as_mut_ptr(),
		}
	}
}

/// Message transport of one party in a multi-party session. `peer` is the index of the other
/// party in the job's party list.
pub trait MpTransport {
	fn send(&self, peer: usize, msg: &[u8]) -> Result<(), TransportError>;
	fn recv(&self, peer: usize) -> Result<Vec<u8>, TransportError>;
}

/// A two-party session over a single [`Transport`]: there is only one peer.
pub struct TwoParty<'a>(pub &'a dyn Transport);

impl MpTransport for TwoParty<'_> {
	fn send(&self, _peer: usize, msg: &[u8]) -> Result<(), TransportError> {
		self.0.send(msg)
	}

	fn recv(&self, _peer: usize) -> Result<Vec<u8>, TransportError> {
		self.0.recv()
	}
}

struct CallbackCtx<'a> {
	transport: &'a dyn MpTransport,
	error: Option<TransportError>,
	panicked: bool,
}

impl CallbackCtx<'_> {
	fn fail(&mut self, e: TransportError) -> ffi::cbmpc_error_t {
		if self.error.is_none() {
			self.error = Some(e);
		}
		ffi::CBMPC_E_NET_GENERAL
	}
}

unsafe fn alloc_copy(bytes: &[u8]) -> *mut u8 {
	let buf = ffi::cbmpc_malloc(bytes.len().max(1)) as *mut u8;
	if !buf.is_null() {
		std::ptr::copy_nonoverlapping(bytes.as_ptr(), buf, bytes.len());
	}
	buf
}

unsafe extern "C" fn cb_send(
	ctx: *mut c_void, receiver: i32, data: *const u8, size: c_int,
) -> ffi::cbmpc_error_t {
	let ctx = &mut *(ctx as *mut CallbackCtx<'_>);
	let res = catch_unwind(AssertUnwindSafe(|| {
		let msg = if size > 0 { std::slice::from_raw_parts(data, size as usize) } else { &[][..] };
		ctx.transport.send(receiver.max(0) as usize, msg)
	}));
	match res {
		Ok(Ok(())) => ffi::CBMPC_SUCCESS,
		Ok(Err(e)) => ctx.fail(e),
		Err(_) => {
			ctx.panicked = true;
			ffi::CBMPC_E_NET_GENERAL
		},
	}
}

unsafe extern "C" fn cb_receive(
	ctx: *mut c_void, sender: i32, out_msg: *mut ffi::cmem_t,
) -> ffi::cbmpc_error_t {
	let ctx = &mut *(ctx as *mut CallbackCtx<'_>);
	*out_msg = ffi::cmem_t::null();
	match catch_unwind(AssertUnwindSafe(|| ctx.transport.recv(sender.max(0) as usize))) {
		Ok(Ok(msg)) => {
			if msg.len() > c_int::MAX as usize {
				return ffi::CBMPC_E_FORMAT;
			}
			let buf = alloc_copy(&msg);
			if buf.is_null() {
				return ffi::CBMPC_E_GENERAL;
			}
			*out_msg = ffi::cmem_t { data: buf, size: msg.len() as c_int };
			ffi::CBMPC_SUCCESS
		},
		Ok(Err(e)) => ctx.fail(e),
		Err(_) => {
			ctx.panicked = true;
			ffi::CBMPC_E_NET_GENERAL
		},
	}
}

unsafe extern "C" fn cb_receive_all(
	ctx: *mut c_void, senders: *const i32, senders_count: c_int, out_msgs: *mut ffi::cmems_t,
) -> ffi::cbmpc_error_t {
	let ctx = &mut *(ctx as *mut CallbackCtx<'_>);
	*out_msgs = ffi::cmems_t { count: 0, data: std::ptr::null_mut(), sizes: std::ptr::null_mut() };
	let senders: &[i32] = if senders_count > 0 {
		std::slice::from_raw_parts(senders, senders_count as usize)
	} else {
		&[]
	};
	let res = catch_unwind(AssertUnwindSafe(|| {
		senders
			.iter()
			.map(|s| ctx.transport.recv((*s).max(0) as usize))
			.collect::<Result<Vec<_>, _>>()
	}));
	match res {
		Ok(Ok(msgs)) => {
			let total: usize = msgs.iter().map(|m| m.len()).sum();
			if total > c_int::MAX as usize {
				return ffi::CBMPC_E_FORMAT;
			}
			let flat: Vec<u8> = msgs.iter().flatten().copied().collect();
			let data = alloc_copy(&flat);
			let sizes =
				ffi::cbmpc_malloc(std::mem::size_of::<c_int>() * msgs.len().max(1)) as *mut c_int;
			if data.is_null() || sizes.is_null() {
				if !data.is_null() {
					ffi::cbmpc_free(data as *mut c_void);
				}
				if !sizes.is_null() {
					ffi::cbmpc_free(sizes as *mut c_void);
				}
				return ffi::CBMPC_E_GENERAL;
			}
			for (i, m) in msgs.iter().enumerate() {
				*sizes.add(i) = m.len() as c_int;
			}
			*out_msgs = ffi::cmems_t { count: msgs.len() as c_int, data, sizes };
			ffi::CBMPC_SUCCESS
		},
		Ok(Err(e)) => ctx.fail(e),
		Err(_) => {
			ctx.panicked = true;
			ffi::CBMPC_E_NET_GENERAL
		},
	}
}

/// This party's share of a TDH2 key, with the public material every party agrees on.
#[derive(Clone, PartialEq, Eq)]
pub struct Tdh2Key {
	/// The joint public key. Anyone can encrypt to it.
	pub public_key: Vec<u8>,
	/// The parties' public shares, in party order.
	pub public_shares: Vec<Vec<u8>>,
	/// This party's private share. Secret key material.
	pub private_share: Vec<u8>,
}

impl fmt::Debug for Tdh2Key {
	fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
		write!(f, "Tdh2Key(<{} parties>)", self.public_shares.len())
	}
}

impl Drop for Tdh2Key {
	fn drop(&mut self) {
		for b in self.private_share.iter_mut() {
			unsafe { std::ptr::write_volatile(b, 0) };
		}
	}
}

impl Tdh2Key {
	/// Serializes the key for storage: public key, public shares, private share.
	pub fn encode(&self) -> Vec<u8> {
		let mut out = vec![1u8];
		let mut put = |b: &[u8]| {
			out.extend_from_slice(&(b.len() as u32).to_be_bytes());
			out.extend_from_slice(b);
		};
		put(&self.public_key);
		put(&self.private_share);
		for share in &self.public_shares {
			put(share);
		}
		out
	}

	pub fn decode(bytes: &[u8]) -> Result<Self, String> {
		if bytes.first() != Some(&1) {
			return Err("unknown TDH2 key version".into());
		}
		let mut rest = &bytes[1..];
		let mut items = Vec::new();
		while !rest.is_empty() {
			if rest.len() < 4 {
				return Err("truncated TDH2 key".into());
			}
			let len = u32::from_be_bytes(rest[..4].try_into().unwrap()) as usize;
			if rest.len() < 4 + len {
				return Err("truncated TDH2 key".into());
			}
			items.push(rest[4..4 + len].to_vec());
			rest = &rest[4 + len..];
		}
		if items.len() < 4 {
			return Err("TDH2 key needs at least two public shares".into());
		}
		let public_shares = items.split_off(2);
		let private_share = items.pop().unwrap();
		let public_key = items.pop().unwrap();
		Ok(Tdh2Key { public_key, public_shares, private_share })
	}

	/// This party's contribution to decrypting `ciphertext`. Sensitive: with every party's
	/// partial decryption anyone can recover the plaintext, so only send it over an encrypted
	/// link to the party meant to combine them.
	pub fn partial_decrypt(&self, ciphertext: &[u8], label: &[u8]) -> Result<Vec<u8>, CbmpcError> {
		unsafe {
			let mut out = ffi::cmem_t::null();
			check(ffi::cbmpc_tdh2_partial_decrypt(
				view(&self.private_share),
				view(ciphertext),
				view(label),
				&mut out,
			))?;
			Ok(take_cmem(out))
		}
	}

	/// Recovers the plaintext from one partial decryption per party, in party order.
	pub fn combine(
		&self, ciphertext: &[u8], label: &[u8], partial_decryptions: &[Vec<u8>],
	) -> Result<Vec<u8>, CbmpcError> {
		combine(&self.public_key, &self.public_shares, ciphertext, label, partial_decryptions)
	}
}

/// Runs the TDH2 distributed key generation among `party_names` on secp256k1. `me` is this
/// party's index. Every party must use the same names in the same order.
pub fn dkg(
	party_names: &[&str], me: usize, transport: &dyn MpTransport,
) -> Result<Tdh2Key, ProtocolError> {
	let names: Vec<CString> = party_names
		.iter()
		.map(|n| CString::new(*n).expect("party name must not contain NUL"))
		.collect();
	let name_ptrs: Vec<*const c_char> = names.iter().map(|n| n.as_ptr()).collect();
	let mut ctx = CallbackCtx { transport, error: None, panicked: false };
	let c_transport = ffi::cbmpc_transport_t {
		ctx: &mut ctx as *mut CallbackCtx<'_> as *mut c_void,
		send: Some(cb_send),
		receive: Some(cb_receive),
		receive_all: Some(cb_receive_all),
		free: None,
	};
	let job = ffi::cbmpc_mp_job_t {
		self_: me as i32,
		party_names: name_ptrs.as_ptr(),
		party_names_count: name_ptrs.len() as c_int,
		transport: &c_transport,
	};
	let res = unsafe {
		let mut public_key = ffi::cmem_t::null();
		let mut public_shares =
			ffi::cmems_t { count: 0, data: std::ptr::null_mut(), sizes: std::ptr::null_mut() };
		let mut private_share = ffi::cmem_t::null();
		let mut sid = ffi::cmem_t::null();
		check(ffi::cbmpc_tdh2_dkg_additive(
			&job,
			ffi::CBMPC_CURVE_SECP256K1,
			&mut public_key,
			&mut public_shares,
			&mut private_share,
			&mut sid,
		))
		.map(|()| {
			let _ = take_cmem(sid);
			Tdh2Key {
				public_key: take_cmem(public_key),
				public_shares: take_cmems(public_shares),
				private_share: take_cmem(private_share),
			}
		})
	};
	if ctx.panicked {
		return Err(ProtocolError::Transport(TransportError(
			"transport callback panicked".to_string(),
		)));
	}
	match res {
		Ok(key) => Ok(key),
		Err(e) => match ctx.error.take() {
			Some(t) => Err(ProtocolError::Transport(t)),
			None => Err(ProtocolError::Cbmpc(e)),
		},
	}
}

/// Encrypts `plaintext` to the joint `public_key`, bound to `label`. Needs no secret.
pub fn encrypt(public_key: &[u8], plaintext: &[u8], label: &[u8]) -> Result<Vec<u8>, CbmpcError> {
	unsafe {
		let mut out = ffi::cmem_t::null();
		check(ffi::cbmpc_tdh2_encrypt(view(public_key), view(plaintext), view(label), &mut out))?;
		Ok(take_cmem(out))
	}
}

/// Checks that `ciphertext` is a well-formed encryption to `public_key` under `label`.
pub fn verify(public_key: &[u8], ciphertext: &[u8], label: &[u8]) -> Result<(), CbmpcError> {
	unsafe { check(ffi::cbmpc_tdh2_verify(view(public_key), view(ciphertext), view(label))) }
}

/// Recovers the plaintext from one partial decryption per party, in party order.
pub fn combine(
	public_key: &[u8], public_shares: &[Vec<u8>], ciphertext: &[u8], label: &[u8],
	partial_decryptions: &[Vec<u8>],
) -> Result<Vec<u8>, CbmpcError> {
	let mut shares = Flat::new(public_shares);
	let mut partials = Flat::new(partial_decryptions);
	unsafe {
		let mut out = ffi::cmem_t::null();
		check(ffi::cbmpc_tdh2_combine_additive(
			view(public_key),
			shares.view(),
			view(label),
			partials.view(),
			view(ciphertext),
			&mut out,
		))?;
		Ok(take_cmem(out))
	}
}

#[cfg(test)]
mod tests {
	use std::thread;
	use std::time::Duration;

	use super::*;
	use crate::transport::ChannelTransport;

	fn keys() -> (Tdh2Key, Tdh2Key) {
		let (ta, tb) = ChannelTransport::pair(Duration::from_secs(30));
		let names = ["party-a", "party-b"];
		let b = thread::spawn(move || dkg(&names, 1, &TwoParty(&tb)).unwrap());
		let a = dkg(&names, 0, &TwoParty(&ta)).unwrap();
		(a, b.join().unwrap())
	}

	#[test]
	fn two_parties_decrypt_together_only() {
		let (a, b) = keys();
		assert_eq!(a.public_key, b.public_key);
		assert_eq!(a.public_shares, b.public_shares);
		assert_ne!(a.private_share, b.private_share);

		let secret = [0x42u8; 32];
		let ct = encrypt(&a.public_key, &secret, b"label-1").unwrap();
		verify(&a.public_key, &ct, b"label-1").unwrap();

		let pa = a.partial_decrypt(&ct, b"label-1").unwrap();
		let pb = b.partial_decrypt(&ct, b"label-1").unwrap();
		assert_eq!(a.combine(&ct, b"label-1", &[pa.clone(), pb.clone()]).unwrap(), secret);

		// One party's contribution is not enough, and neither is the same one twice.
		assert!(a.combine(&ct, b"label-1", std::slice::from_ref(&pa)).is_err());
		assert!(a.combine(&ct, b"label-1", &[pa.clone(), pa.clone()]).is_err());
	}

	#[test]
	fn label_binds_the_ciphertext() {
		let (a, b) = keys();
		let ct = encrypt(&a.public_key, &[7u8; 32], b"kit-1/100").unwrap();
		assert!(verify(&a.public_key, &ct, b"kit-1/99").is_err());
		assert!(a.partial_decrypt(&ct, b"kit-1/99").is_err());
		let pa = a.partial_decrypt(&ct, b"kit-1/100").unwrap();
		let pb = b.partial_decrypt(&ct, b"kit-1/100").unwrap();
		assert!(a.combine(&ct, b"kit-1/99", &[pa, pb]).is_err());
	}

	#[test]
	fn key_round_trips_through_storage() {
		let (a, _) = keys();
		assert_eq!(Tdh2Key::decode(&a.encode()).unwrap(), a);
		assert!(Tdh2Key::decode(&[2, 0]).is_err());
	}
}
